"use client";

import { useState } from "react";
import Link from "next/link";
import { FiMenu, FiX } from "react-icons/fi";

export default function CustomNavBar() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className="bg-white p-4 sticky top-0 w-full z-50 shadow-2xl">
      <div className="container mx-auto flex items-center justify-between">
        <h1 className="text-xl font-bold">Viksit Bharat</h1>
        <div className="hidden md:flex space-x-6">
          <Link href="/#Home" className="hover:underline">
            Home
          </Link>
          <Link href="/#About Us" className="hover:underline">
            About
          </Link>
          <Link href="/#Mission" className="hover:underline">
            Mission
          </Link>
          <Link href="/#Contact Us" className="hover:underline">
            Contact Us
          </Link>
        </div>
        <button className="md:hidden " onClick={() => setIsOpen(!isOpen)}>
          {isOpen ? <FiX /> : <FiMenu />}
        </button>
      </div>
      {isOpen && (
        <div className="md:hidden flex flex-col items-center space-y-4 mt-4 bg-white p-4">
          <Link
            href="/"
            className=" hover:underline"
            onClick={() => setIsOpen(false)}
          >
            Home
          </Link>
          <Link
            href="/about"
            className=" hover:underline"
            onClick={() => setIsOpen(false)}
          >
            About
          </Link>
          <Link
            href="/contact"
            className=" hover:underline"
            onClick={() => setIsOpen(false)}
          >
            Contact
          </Link>
        </div>
      )}
    </div>
  );
}
